// TestContainersBuilderClone pins that a clone can be configured on its own.
func TestContainersBuilderClone(t *testing.T) {
	t.Parallel()

	t.Run("carries the configuration across", func(t *testing.T) {
		t.Parallel()
		// A clone starting from nothing would be a second constructor under
		// another name, and a test cloning a configured builder would silently
		// lose everything it had set.
		b := domaintest.NewContainers()
		testkit.Equal(t, b.Clone().Build(), b.Build(), "a clone starts where its original stood")
	})

	t.Run("does not share Slice with its original", func(t *testing.T) {
		t.Parallel()
		// Shared backing storage makes one test's setup visible in another's,
		// which surfaces as a failure for something the test never did.
		var v string
		b := domaintest.NewContainers().WithSlice(v)
		b.Clone().AppendSlice(v)
		testkit.Equal(t, len(b.Build().Slice), 1,
			"appending to a clone must not reach the original")
	})

	t.Run("does not share SliceOfStruct with its original", func(t *testing.T) {
		t.Parallel()
		// Shared backing storage makes one test's setup visible in another's,
		// which surfaces as a failure for something the test never did.
		var v domain.Address
		b := domaintest.NewContainers().WithSliceOfStruct(v)
		b.Clone().AppendSliceOfStruct(v)
		testkit.Equal(t, len(b.Build().SliceOfStruct), 1,
			"appending to a clone must not reach the original")
	})

	t.Run("does not share Body with its original", func(t *testing.T) {
		t.Parallel()
		// A byte slice is copied like any other, and a clone sharing its
		// backing array would let one test's bytes appear in another's.
		b := domaintest.NewContainers().WithBodyString("seed")
		testkit.Equal(t, string(b.Clone().Build().Body), "seed",
			"a clone carries Body across")
	})

	t.Run("does not share Aliased with its original", func(t *testing.T) {
		t.Parallel()
		// A byte slice is copied like any other, and a clone sharing its
		// backing array would let one test's bytes appear in another's.
		b := domaintest.NewContainers().WithAliasedString("seed")
		testkit.Equal(t, string(b.Clone().Build().Aliased), "seed",
			"a clone carries Aliased across")
	})

	t.Run("does not share Map with its original", func(t *testing.T) {
		t.Parallel()
		var k string
		var v string
		b := domaintest.NewContainers().WithMapEntry(k, v)
		b.Clone().WithMapEntries(map[string]string{})
		testkit.Equal(t, len(b.Build().Map), 1,
			"configuring a clone must not reach the original")
	})

	t.Run("does not share MapOfStruct with its original", func(t *testing.T) {
		t.Parallel()
		var k string
		var v domain.Address
		b := domaintest.NewContainers().WithMapOfStructEntry(k, v)
		b.Clone().WithMapOfStructEntries(map[string]domain.Address{})
		testkit.Equal(t, len(b.Build().MapOfStruct), 1,
			"configuring a clone must not reach the original")
	})
}

